/// <reference path="../pb_data/types.d.ts" />
/**
 * A2App operation routes - GENERATED by tools/agent-app-migrate from the app's own
 * routes (agent-owned; regenerate rather than hand-edit).
 *
 * Every declared operation is served at POST /api/ops/<name> by the SAME handler
 * the app's screens call at their own path. The framework adapter has already
 * checked the caller, the arguments and (destructive) the person's approval; op()
 * answers with the protocol envelope.
 */

// POST /api/ops/ai/generate (ops.pb.js)
routerAdd("POST", "/api/ops/ai.generate", (e) => require(`${__hooks}/_a2app_impl.js`).op(e, "ai.generate", (ev) => ((e) => {
  const bridge = require(`${__hooks}/_craftbot_bridge.js`);
  const body = e.requestInfo().body || {};
  const prompt = String(body.prompt || '');
  const system = String(body.system || '');
  if (prompt === '') {
    return e.json(400, { error: 'prompt is required' });
  }
  const raw = bridge.callLLM(prompt, system);
  return e.json(200, { text: raw || '' });
})(ev)));

// GET /api/ops/integrations/status (ops.pb.js)
routerAdd("POST", "/api/ops/integrations.status", (e) => require(`${__hooks}/_a2app_impl.js`).op(e, "integrations.status", (ev) => ((e) => {
  // Any host's model: CraftBot's bridge or a running framework bridge (_craftbot_bridge.llmAvailable).
  const configured = require(`${__hooks}/_craftbot_bridge.js`).llmAvailable();
  return e.json(200, { llmAvailable: configured });
})(ev)));

